import{z as i,x as n,o as A,c as s,q as e,j as B,D as a,d as l,s as o,S as r}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"TCA 的深化与陷阱","description":"","frontmatter":{"title":"TCA 的深化与陷阱","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ex-tca-deep-pitfalls.md","filePath":"quant/ex-tca-deep-pitfalls.md","lastUpdated":1791063341000}'),p={name:"quant/ex-tca-deep-pitfalls.md"};function d(C,E,u,F,h,T){const t=n("Mermaid");return A(),s("div",null,[E[2]||(E[2]=e('<h1 id="tca-的深化与陷阱" tabindex="-1">TCA 的深化与陷阱 <a class="header-anchor" href="#tca-的深化与陷阱" aria-label="Permalink to &quot;TCA 的深化与陷阱&quot;">​</a></h1><div class="epigraph"><p>TCA 的每个数字都是估计量：有方差、有偏、且被考核重塑行为；不写抽样与口径的 TCA 报告，只是一张记分牌。</p><footer>—— 据 Perold, The Implementation Shortfall, Journal of Portfolio Management, 1988；Berkowitz, Logue and Noser, Journal of Finance, 1988 整理</footer></div><p><a href="/quant/ex-multiasset">上一课</a>把组合缺口定为唯一加总口径。主干 <a href="/quant/tca">成交后分析 TCA</a> 与 <a href="/quant/slippage-attribution">滑点归因</a> 给了基准与拆项；度量与案例单元由此进入。本课不加新科目，写的是把它当计量来做：统计功效、选择偏误、被 KPI 重塑的行为。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>交易台常见的比较：算法 A 本季相对到达价省 3 个基点，算法 B 费 1 个基点，结论换 A。单笔母单滑点的标准差常以几十个基点计，每季几百笔的均值标准误仍在 1–2 个基点量级——4 个基点的差距可能全是噪声。更隐蔽的是偏误：被取消的母单常不进报表（它们恰是被动等待失败的部分）；经纪商考核用经纪商自报的样本；暗池打印滞后使场所间时间窗不可比。方差与偏误未声明时，一切「谁更好」都不可证伪。</p><p><span class="marginnote">标准误回答的是「均值本身有多不确定」：单笔滑点上下几十个基点，几百笔平均后才缩到 1–2 个基点。看到 4 个基点的差距，先问一句这个差距有没有量准，再谈谁更好。</span></p>',6)),(A(),B(r,null,{default:a(()=>[o(t,{id:"mermaid-16",class:"mermaid",graph:"flowchart%20TD%0A%20%20POP%5B%22%E5%85%A8%E9%83%A8%E6%AF%8D%E5%8D%95%2C%20%E5%90%AB%E5%A4%B1%E8%B4%A5%E4%B8%8E%E5%8F%96%E6%B6%88%22%5D%20--%3E%20FILT%7B%22%E6%8A%A5%E8%A1%A8%E5%8F%AA%E6%94%B6%E8%B0%81%3F%22%7D%0A%20%20FILT%20--%3E%7C%22%E5%8F%AA%E6%94%B6%E6%88%90%E4%BA%A4%E5%8D%95%22%7C%20BIAS%5B%22%E8%A2%AB%E5%8A%A8%E4%B8%8E%E7%AD%89%E5%BE%85%E7%AD%96%E7%95%A5%E8%A2%AB%E7%B3%BB%E7%BB%9F%E6%80%A7%E7%BE%8E%E5%8C%96%22%5D%0A%20%20FILT%20--%3E%7C%22%E5%85%A8%E9%87%8F%E5%85%A5%E6%A0%B7%2C%20%E5%8F%96%E6%B6%88%E5%8D%95%E5%88%97%22%7C%20OK%5B%22%E4%B8%BB%E5%8A%A8%E5%A4%B1%E8%B4%A5%E7%9A%84%E4%BB%A3%E4%BB%B7%E5%A6%82%E5%AE%9E%E5%85%A5%E8%B4%A6%22%5D%0A%20%20POP%20--%3E%20PICK%7B%22%E6%A0%B7%E6%9C%AC%E8%B0%81%E6%8A%A5%3F%22%7D%0A%20%20PICK%20--%3E%7C%22%E7%BB%8F%E7%BA%AA%E5%95%86%E8%87%AA%E6%8A%A5%22%7C%20SEL%5B%22%E6%A0%B7%E6%9C%AC%E9%80%89%E6%8B%A9%E4%B8%8E%E7%9C%9F%E5%AE%9E%E6%8A%80%E8%83%BD%E6%B7%B7%E5%90%8C%22%5D%0A%20%20PICK%20--%3E%7C%22%E9%9A%8F%E6%9C%BA%E5%88%86%E6%B5%81%22%7C%20FAIR%5B%22%E8%AF%84%E5%87%BA%E6%9D%A5%E7%9A%84%E6%98%AF%E6%89%A7%E8%A1%8C%E8%B4%A8%E9%87%8F%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e('<p>第二层是激励。TCA 指标同时是考核指标时，被度量者会优化指标而不是成本：把到达时点后挪让参照价更有利、把截止前的成交对齐基准、把难做的单推进不计入的时段。</p><h3 id="功效、分层与配对" tabindex="-1">功效、分层与配对 <a class="header-anchor" href="#功效、分层与配对" aria-label="Permalink to &quot;功效、分层与配对&quot;">​</a></h3><p>功效先行：解读差距前先算标准误——按母单聚合的自助法置信区间，不把子单当独立样本（子单共享冲击与时机）。分层轴必须全是<strong>事前</strong>变量：波动桶、规模对 ADV、紧急度、日期类型（指数日、事件日单独成层，见 <a href="/quant/ex-vol-execution">波动执行的专门问题</a>）；用事后结果分层等于把答案藏进分层里。配对优先于前后比较：同类母单在两条规则间随机轮换（A/B），把行情作共同项差掉；做不了随机化时，把滑点对同期对照收益回归，取残差比较。</p><p><span class="marginnote">最低样本量可以反推：要检出 3 个基点、单笔标准差 30 个基点的差距，约需 \\((2\\times1.96\\times30/3)^2\\approx 1500\\) 笔母单；多数交易台一个季度、按算法各分到几百笔就下结论，功效严重不足。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>口径审计清单，逐项过：参照价的到达时点定义（决策价与到达价分列，见 <a href="/quant/slippage-attribution">滑点归因</a>）；未完成与已取消的会计处理（取消母单单列）；费用与返佣的净额口径（返佣记负费用会诱导路由偏向返佣所）；暗池与跨所打印的时间基准；金额加权与等权两套并报。口径冻结在度量规范里随代码版本管理；改口径的历史在页脚披露。</p><p><span class="marginnote">返佣是经纪商按成交量返给客户的回扣。把返佣记成负费用，报表成本立刻变低，但它诱导路由偏向给返佣的场所——账面省了钱，真实成交成本未必省，这就是「口径改变行为」的典型例子。</span></p><p>制度性实验：路由与日程参数的变更走 A/B 轮换或阶梯 rollout，保留随机化种子；无法实验时用断点或对照集并声明设计。经纪商与场所的评价只基于随机分流——把容易的单分给某家再考核滑点，评出来的是分流规则不是执行质量。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么偏误方向可预测：主动规则的失败单更容易被取消（价格走掉了），「只算成交单」系统性美化被动与等待策略；赢了评比的经纪商吸引更多流量，样本选择与真实技能混同。为什么窗口期是战场：截止前的对齐让「贴基准」变好而总成本不变甚至更差，Perold 用纸面组合定义缺口，就是为切断对基准的循环引用。方差侧，共同行情使有效样本量小于名义样本量：同一日的几十笔母单共享一个市场运动，按日分块的自助法才是诚实的不确定度。</p>',10)),(A(),B(r,null,{default:a(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22%E5%8E%9F%E5%A7%8B%E6%88%90%E4%BA%A4%E4%B8%8E%E6%AF%8D%E5%8D%95%E6%97%A5%E5%BF%97%22%5D%20--%3E%20AUD%7B%22%E5%8F%A3%E5%BE%84%E5%AE%A1%E8%AE%A1%3A%20%E5%8F%82%E7%85%A7%20%2F%20%E5%8F%96%E6%B6%88%20%2F%20%E8%B4%B9%E7%94%A8%20%2F%20%E6%97%B6%E9%92%9F%22%7D%0A%20%20AUD%20--%3E%20STAT%5B%22%E6%8C%89%E6%AF%8D%E5%8D%95%E8%81%9A%E5%90%88%2C%20%E5%88%86%E5%B1%82%2C%20%E8%87%AA%E5%8A%A9%E6%B3%95%E5%8C%BA%E9%97%B4%22%5D%0A%20%20STAT%20--%3E%20AB%7B%22A%2FB%20%E6%88%96%E5%AF%B9%E7%85%A7%3F%22%7D%0A%20%20AB%20--%3E%7C%E6%9C%89%7C%20DIFF%5B%22%E5%B7%AE%E5%88%86%E8%A1%8C%E6%83%85%E5%85%B1%E5%90%8C%E9%A1%B9%22%5D%0A%20%20AB%20--%3E%7C%E6%97%A0%7C%20REG%5B%22%E5%AF%B9%E5%AF%B9%E7%85%A7%E6%94%B6%E7%9B%8A%E5%9B%9E%E5%BD%92%E5%8F%96%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20DIFF%20--%3E%20GOV%5B%22%E6%B2%BB%E7%90%86%3A%20%E4%B8%BB%E5%9F%BA%E5%87%86%E5%86%BB%E7%BB%93%2C%20%E5%8F%A3%E5%BE%84%E7%89%88%E6%9C%AC%E5%8C%96%22%5D%0A%20%20REG%20--%3E%20GOV%0A%20%20GOV%20--%3E%20DEC%5B%22%E5%8F%82%E6%95%B0%20%2F%20%E7%BB%8F%E7%BA%AA%E5%95%86%20%2F%20%E5%9C%BA%E6%89%80%E5%86%B3%E7%AD%96%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=e('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>TCA 无法在没有实验的情况下证明因果：场所对比永远有「那家拿到的单不一样」的竞争假说。跨资产不可比：外汇点差惯例、期货展期与结算价使股票式基点口径失真。单季度是一个体制样本，<a href="/quant/ex-vol-execution">波动执行的专门问题</a> 的分层必须前置而不是事后剔除。度量基础设施有成本与时滞：时间戳与时钟同步决定几个基点的分辨率。TCA 回答「做得好不好」，回答不了「该不该做」——后者是 <a href="/quant/ex-cost-forecast">成本预测模型</a> 的事前问题。</p><p><span class="marginnote">初学者容易把 TCA 报表当客观记分牌，实际上从参照价取哪格时间戳、到取消单算不算，每一步都是可争议的建模决策。先审口径再看数字，否则比较的可能只是两份报表的制作方式。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>TCA 数字是估计量：先报标准误与有效样本量再谈差距；子单不是独立样本。</li><li>分层轴全部事前；取消与未完成母单单列，否则被动策略被美化。</li><li>配对实验优于前后比较；口径清单（参照价、取消、返佣、时钟）冻结并版本化。</li><li>基准窗口是对齐行为的战场；Perold 的纸面组合口径切断循环引用。</li><li>经纪商与场所评价只认随机分流的流量；单季度结论按体制分层。</li><li>TCA 管事后评价，成本预测管事前决策，两个方向不可越界。</li><li>出处：Perold, <em>JPM</em>, 1988；Berkowitz, Logue and Noser, <em>Journal of Finance</em>, 1988；分解框架见 Kissell 的执行质量论述。</li></ul>',5))])}const m=i(p,[["render",d]]);export{c as __pageData,m as default};
